it.effect("proves SDK legacy boundaries without inventing historical graph turns or prompting", () =>
  Effect.gen(function* () {
    const nativeSessionId = "ses_legacy_metadata";
    const native = {
      id: nativeSessionId, directory: "/workspace", title: "Existing native conversation",
      time: { created: 1, updated: 3 },
    };
    const user: UserMessage = {
      id: "msg_legacy_user", sessionID: nativeSessionId, role: "user", time: { created: 1 },
      agent: "build", model: { providerID: "native-api", modelID: "model/one", variant: "high" },
    };
    const assistant: AssistantMessage = {
      id: "msg_legacy_answer", sessionID: nativeSessionId, role: "assistant", parentID: user.id,
      modelID: "model/one", providerID: "native-api", mode: "build", agent: "build",
      path: { cwd: "/workspace", root: "/workspace" }, time: { created: 2, completed: 3 },
      finish: "stop", cost: 0, tokens: { input: 0, output: 0, reasoning: 0, cache: { read: 0, write: 0 } },
    };
    let creates = 0;
    let prompts = 0;
    const harness = yield* makeOpenCodeRuntimeHarness("legacy-metadata", nativeSessionId, {
      event: { subscribe: asyncEventStream().subscribe },
      session: {
        create: async () => { creates++; return { data: native }; },
        get: async () => ({ data: native }),
        status: async () => ({ data: {} }),
        messages: async () => ({ data: [{ info: user, parts: [] }, { info: assistant, parts: [] }] }),
        promptAsync: async () => { prompts++; return { data: true }; },
      },
    });
    const evidence = OpenCodeRuntime.readOpenCodeSessionEvidence(harness.runtime);
    assert.isDefined(evidence);
    if (evidence === undefined) throw new Error("Original native evidence missing");
    const snapshot = yield* evidence.readLegacy({
      nativeSessionId, turnId: user.id, messageId: user.id,
      ensure: { threadId: harness.threadId, runtimePolicy: harness.policy,
        modelSelection: { instanceId: harness.runtime.instanceId, model: "native-api/model/one" } },
    });
    assert.equal(snapshot.providerThread.nativeThreadRef?.nativeId, nativeSessionId);
    assert.equal(snapshot.providerThread.nativeConversationHeadRef?.nativeId, user.id);
    assert.equal(snapshot.providerThread.nativeMetadata?.forkHeadMessageId, assistant.id);
    assert.deepStrictEqual(snapshot.providerThread.nativeMetadata?.modelSelection, {
      instanceId: harness.runtime.instanceId, model: "native-api/model/one",
      options: [{ id: "variant", value: "high" }],
    });
    assert.deepStrictEqual(snapshot.providerTurns, []);
    assert.deepStrictEqual(snapshot.nativeHistory, {
      nativeSessionId,
      completedTurnRefs: [{ driver: OPENCODE_PROVIDER, nativeId: user.id, strength: "strong" }],
      latestCompletedTurnRef: { driver: OPENCODE_PROVIDER, nativeId: user.id, strength: "strong" },
    });
    assert.equal(creates, 1, "Metadata adoption must not call ensure/create again");
    assert.equal(prompts, 0);
  }).pipe(
    Effect.provide(Layer.merge(IdAllocator.layer, openCodeTestRuntimeHostLayer)),
    Effect.scoped,
  ),
);

it.effect.each(["completed", "unfinished", "failed", "tool-calls", "error-finish", "reverted", "foreign-session", "foreign-cwd"] as const)(
  "keeps only SDK-proven native history with a %s final message",
  (mode) => Effect.gen(function* () {
    const nativeSessionId = "ses_native_history";
    const firstUser: UserMessage = {
      id: "msg_first_user", sessionID: nativeSessionId, role: "user", time: { created: 1 },
      agent: "build", model: { providerID: "native-api", modelID: "model/one" },
    };
    const firstAssistant: AssistantMessage = {
      id: "msg_first_answer", sessionID: nativeSessionId, role: "assistant", parentID: firstUser.id,
      modelID: "model/one", providerID: "native-api", mode: "build", agent: "build",
      path: { cwd: "/workspace", root: "/workspace" }, time: { created: 2, completed: 3 },
      finish: "stop", cost: 0, tokens: { input: 0, output: 0, reasoning: 0, cache: { read: 0, write: 0 } },
    };
    const laterUser: UserMessage = { ...firstUser, id: "msg_later_user", time: { created: 4 } };
    const laterAssistant: AssistantMessage = {
      ...firstAssistant, id: "msg_later_answer", parentID: laterUser.id,
      sessionID: mode === "foreign-session" ? "ses_other" : nativeSessionId,
      path: { cwd: mode === "foreign-cwd" ? "/another-directory" : "/workspace", root: "/workspace" },
      time: { created: 5, ...(mode === "unfinished" ? {} : { completed: 6 }) },
      finish: mode === "tool-calls" ? "tool-calls" : mode === "error-finish" ? "error" : "stop",
      ...(mode === "failed" ? { error: { name: "MessageAbortedError" as const, data: { message: "Interrupted" } } } : {}),
    };
    const native = {
      id: nativeSessionId, directory: "/workspace", title: "Native history", time: { created: 1, updated: 6 },
      ...(mode === "reverted" ? { revert: { messageID: laterUser.id } } : {}),
    };
    const harness = yield* makeOpenCodeRuntimeHarness(`native-history-${mode}`, nativeSessionId, {
      event: { subscribe: asyncEventStream().subscribe },
      session: {
        create: async () => ({ data: native }),
        get: async () => ({ data: native }),
        messages: async () => ({ data: [
          { info: firstUser, parts: [] }, { info: firstAssistant, parts: [] },
          { info: laterUser, parts: [] }, { info: laterAssistant, parts: [] },
        ] }),
      },
    });
    const snapshot = yield* harness.runtime.readThreadSnapshot({ providerThread: harness.providerThread });
    const first = { driver: OPENCODE_PROVIDER, nativeId: firstUser.id, strength: "strong" as const };
    const later = { driver: OPENCODE_PROVIDER, nativeId: laterUser.id, strength: "strong" as const };
    assert.deepStrictEqual(snapshot.providerTurns, []);
    assert.equal(snapshot.providerThread.nativeConversationHeadRef?.strength, "weak");
    assert.deepStrictEqual(snapshot.nativeHistory, {
      nativeSessionId,
      completedTurnRefs: mode === "completed" ? [first, later] : [first],
      ...(mode === "completed" ? { latestCompletedTurnRef: later } : mode === "reverted" ? { latestCompletedTurnRef: first } : {}),
    });
  }).pipe(
    Effect.provide(Layer.merge(IdAllocator.layer, openCodeTestRuntimeHostLayer)),
    Effect.scoped,
  ),
);

